// ===== VERDICT LEDGER (read): yesterday's analysis as challengeable prior =====
combined.previousAnalysis = 'No prior analysis available.';
combined.trackRecordAccuracy = 'Building history';
combined.trackRecordLast = '';
try {
  const sd = $getWorkflowStaticData('global');
  const led = (sd.mpLedger && sd.mpLedger['CN']) || [];
  const prev = led.length ? led[led.length - 1] : null;
  if (prev && prev.date) {
    let t = 'On ' + prev.date + ' your sentiment was ' + prev.sentiment + ' (confidence ' + prev.confidence + '; verification verdict ' + prev.verdict + ').';
    if (Array.isArray(prev.claims) && prev.claims.length) {
      t += ' Your claims were: ' + prev.claims.map(function(c){ return '"' + c.claim + '" [based on: ' + (c.basedOn || []).join(', ') + ']'; }).join('; ') + '.';
    }
    combined.previousAnalysis = t;
  }

  // ===== TRACK RECORD (deterministic, code-only, never a prediction): was
  // yesterday's stated sentiment consistent with what the market actually did
  // next? Purely retrospective - the LLM is never asked about the future. =====
  if (!sd.mpTrackRecord) sd.mpTrackRecord = {};
  if (!sd.mpTrackRecord.CN) sd.mpTrackRecord.CN = [];
  const tr = sd.mpTrackRecord.CN;
  const todayChangeStr = combined.csi300Change;
  const todayChange = (todayChangeStr && todayChangeStr !== 'N/A') ? parseFloat(todayChangeStr) : NaN;
    // ===== STALENESS GUARD (2026-07-14) =====
  // The scorer compares "yesterday's call" against "today's move". That is only
  // meaningful if the prior entry really is the previous trading day. When a run FAILS
  // (e.g. the 07-13 US run died on a Gemini 503), the next run would otherwise score a
  // stale call against a move it never covered - and record it as if it were consecutive.
  // A track record is worth nothing if it quietly scores the wrong days. 4 days covers a
  // long weekend; beyond that we cannot honestly attribute the move, so we skip.
  let gapDays = null;
  if (prev && prev.date) {
    gapDays = Math.round((new Date().setHours(0,0,0,0) - new Date(prev.date + "T00:00:00").getTime()) / 86400000);
  }
  const scoreable = gapDays !== null && gapDays >= 1 && gapDays <= 4;
  if (prev && prev.sentiment && !isNaN(todayChange) && !scoreable) {
    console.error("🟠 [MarketPulse][TRACK-RECORD] skipped: prior call is " + gapDays + " days old (a run was likely missed) - cannot honestly attribute today's move to it");
  }
  if (prev && prev.sentiment && !isNaN(todayChange) && scoreable) {
    const bullish = /Bullish/i.test(prev.sentiment);
    const bearish = /Bearish/i.test(prev.sentiment);
    let result;
    if (bullish) result = todayChange > 0 ? 'hit' : 'miss';
    else if (bearish) result = todayChange < 0 ? 'hit' : 'miss';
    else result = Math.abs(todayChange) < 0.5 ? 'hit' : 'miss'; // Neutral: correct only if the market was actually quiet
    tr.push({ priorDate: prev.date, scoredDate: new Date().toISOString().slice(0, 10), priorSentiment: prev.sentiment, actualChange: todayChangeStr, result: result, gapDays: gapDays });
    if (tr.length > 30) tr.splice(0, tr.length - 30);
    const hits = tr.filter(function (x) { return x.result === 'hit'; }).length;
    combined.trackRecordAccuracy = hits + '/' + tr.length + ' (' + Math.round(100 * hits / tr.length) + '%)';
    const last = tr[tr.length - 1];
    combined.trackRecordLast = last.priorSentiment + ' (' + last.priorDate + ') → market moved ' + last.actualChange + ' → ' + (last.result === 'hit' ? 'Correct' : 'Miss');
  }
} catch (e) { console.log('[MarketPulse][LEDGER] read/trackrecord skipped: ' + (e && e.message)); }


if (!combined._health) {
  combined._health = {
    status: 'OUTAGE',
    failed: [{ source: 'ALL', code: 'NO_DATA', msg: 'Fetch node produced no output this run (timeout, crash, or task-runner failure) - see n8n execution log' }],
    missing: ['ALL']
  };
  console.error('\u{1F534} [MarketPulse][DATA-HEALTH] OUTAGE | Fetch node returned nothing at all this run (total upstream failure)');
}

return [{ json: combined }];

