for (const it of items) {
  const j = (it && it.json) || {};
  for (const k of Object.keys(j)) if (gt[k] === undefined) gt[k] = j[k];
  if (j._health) health = j._health;
  if (typeof j.text === 'string' && j.text.length > 30) llmText = j.text;
  if (typeof j.response === 'string' && j.response.length > 30) llmText = j.response;
}
if (!llmText && typeof gt.llmAnalysis === 'string') llmText = gt.llmAnalysis;

const num = (s) => {
  if (s === undefined || s === null) return NaN;
  const mm = String(s).replace(/,/g, '').match(/-?\d+(\.\d+)?/);
  return mm ? parseFloat(mm[0]) : NaN;
};
const F = (label, raw, kind, kw) => ({ label, n: num(raw), kind, kw });
// Detect edition from which ground-truth fields are present (US and CN branches are separate)
const edition = (gt.csi300 !== undefined || gt.sseComposite !== undefined || gt.hangSeng !== undefined) ? 'CN' : 'US';
const US_FACTS = [
  F('S&P 500', gt.sp500, 'level', ['s&p', 'sp500']),
  F('S&P 500 change', gt.sp500Change, 'pct', ['s&p', 'sp500']),
  F('Dow Jones', gt.dowJones, 'level', ['dow']),
  F('VIX', gt.vix, 'ratio', ['vix', 'volatility']),
  F('Gold', gt.gold, 'level', ['gold']),
  F('Oil', gt.oil, 'level', ['oil', 'wti', 'crude']),
  F('Bitcoin', gt.btc, 'level', ['bitcoin', 'btc']),
  F('Buffett Indicator', gt.buffettIndicator, 'pct', ['buffett', 'market cap to gdp']),
  F('CAPE', gt.shillerPE, 'ratio', ['cape', 'shiller', 'p/e', 'pe ratio']),
  F('Yield curve', gt.yieldCurve, 'pct', ['yield curve', 'spread']),
  F('S&P vs 200DMA', gt.sp500VsMa200, 'pct', ['200-day', '200d', 'moving average']),
  F('Fear & Greed', gt.fearGreedValue, 'score', ['fear & greed', 'fear and greed', 'sentiment']),
  F('GDP', gt.gdpValue, 'pct', ['gdp']),
  F('CPI', gt.cpiValue, 'pct', ['cpi', 'inflation']),
  F('Unemployment', gt.unemploymentValue, 'pct', ['unemployment', 'jobless']),
  F('Fed funds rate', gt.fedRateValue, 'pct', ['fed funds', 'fed rate', 'federal funds']),
  F('10Y Treasury', gt.treasury10Y, 'pct', ['10y', '10-year', '10 year']),
  F('2Y Treasury', gt.treasury2Y, 'pct', ['2y', '2-year', '2 year']),
];
const CN_FACTS = [
  F('CSI 300', gt.csi300, 'level', ['csi 300', 'csi300', 'csi']),
  F('CSI 300 change', gt.csi300Change, 'pct', ['csi 300', 'csi300', 'csi']),
  F('SSE Composite', gt.sseComposite, 'level', ['sse composite', 'shanghai composite', 'shanghai', 'sse']),
  F('SSE change', gt.sseCompositeChange, 'pct', ['sse composite', 'shanghai composite', 'shanghai', 'sse']),
  F('SZSE Component', gt.szseComponent, 'level', ['szse', 'shenzhen']),
  F('SZSE change', gt.szseComponentChange, 'pct', ['szse', 'shenzhen']),
  F('Hang Seng', gt.hangSeng, 'level', ['hang seng', 'hsi', 'hong kong']),
  F('Hang Seng change', gt.hangSengChange, 'pct', ['hang seng', 'hsi', 'hong kong']),
  F('Gold', gt.gold, 'level', ['gold']),
  F('USD/CNY', gt.usdCny, 'ratio', ['usd/cny', 'cny', 'yuan', 'renminbi', 'rmb']),
  F('GDP', gt.gdpValue, 'pct', ['gdp']),
  F('CPI', gt.cpiValue, 'pct', ['cpi', 'inflation']),
  F('Unemployment', gt.unemploymentValue, 'pct', ['unemployment', 'jobless']),
];
const facts = (edition === 'CN' ? CN_FACTS : US_FACTS).filter(f => !isNaN(f.n));

const tol = (k) => k === 'score' ? 1 : 0.2;
const matches = (f, val) => f.kind === 'level'
  ? Math.abs(f.n - val) / Math.max(f.n, 1) <= 0.006
  : Math.abs(f.n - val) <= tol(f.kind);

const v = { status: 'PASS', score: 100, contradictions: [], unverified: [], checked: 0, mode: MODE, action: 'none', edition };

// ===== VERDICT LEDGER (write): persist today's verdict for tomorrow's prior =====
const writeLedger = (structuredObj) => {
  try {
    const sd = $getWorkflowStaticData('global');
    if (!sd.mpLedger) sd.mpLedger = {};
    if (!sd.mpLedger[edition]) sd.mpLedger[edition] = [];
    const today = new Date().toISOString().slice(0, 10);
    const entry = {
      date: today, edition,
      sentiment: structuredObj ? structuredObj.sentiment : null,
      confidence: structuredObj ? structuredObj.confidence : null,
      claims: structuredObj && Array.isArray(structuredObj.claims)
        ? structuredObj.claims.slice(0, 6).map((c) => ({ claim: String(c.claim || '').slice(0, 200), basedOn: c.basedOn || [] }))
        : [],
      verdict: v.status, score: v.score, violations: v.contradictions.length,
      health: (health && health.status) || 'unknown'
    };
    const led = sd.mpLedger[edition];
    if (led.length && led[led.length - 1].date === today) led[led.length - 1] = entry; else led.push(entry);
    if (led.length > 30) led.splice(0, led.length - 30);
    console.log('[MarketPulse][LEDGER] wrote ' + edition + ' ' + today + ' verdict=' + v.status);
  } catch (e) { console.error('[MarketPulse][LEDGER] write skipped: ' + (e && e.message)); }
};

const lc = llmText.toLowerCase();
const escapeRe = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

// ===== STRUCTURED-GENERATION LAYER (v3): reasoning-attribution verification =====
// The LLM must return JSON claims citing basedOn factKeys; numbers are injected
// downstream from ground truth. Here we verify every attribution deterministically.
let parsed = null;
(function () {
  let t = String(llmText || '').trim();
  const f = t.indexOf('{'), l = t.lastIndexOf('}');
  if (f === -1 || l <= f) return;
  try {
    const o = JSON.parse(t.slice(f, l + 1));
    if (o && typeof o === 'object' && Array.isArray(o.claims)) parsed = o;
  } catch (e) { /* falls through to legacy free-text verification */ }
})();
if (parsed) {
  v.structured = true;
  const KEYS = edition === 'CN'
    ? { csi300: 1, csi300Change: 1, sseComposite: 1, sseCompositeChange: 1, szseComponent: 1, szseComponentChange: 1, hangSeng: 1, hangSengChange: 1, gold: 1, goldChange: 1, usdCny: 1, usdCnyChange: 1, gdpValue: 1, cpiValue: 1, unemploymentValue: 1 }
    : { buffettIndicator: 1, shillerPE: 1, yieldCurve: 1, sp500VsMa200: 1, maSignal: 1, fearGreedValue: 1, sp500: 1, sp500Change: 1, dowJones: 1, dowJonesChange: 1, vix: 1, vixChange: 1, gold: 1, goldChange: 1, oil: 1, oilChange: 1, dxy: 1, dxyChange: 1, btc: 1, btcChange: 1, gdpValue: 1, cpiValue: 1, unemploymentValue: 1, fedRateValue: 1, treasury10Y: 1, treasury2Y: 1 };
  const stripStruct = (s) => String(s || '').replace(/s&p ?500|200[- ]?(?:day|d|dma|ma)\b|10[- ]?(?:y\b|year)|2[- ]?(?:y\b|year)|csi ?300|\/100|0-100/gi, ' ');
  const claims = parsed.claims.slice(0, 6);
  if (!claims.length) v.contradictions.push('structured output has no claims');
  for (const c of claims) {
    const keys = Array.isArray(c.basedOn) ? c.basedOn : [];
    if (!keys.length) v.contradictions.push('claim lacks attribution (empty basedOn): ' + String(c.claim).slice(0, 60));
    for (const k of keys) {
      const hm = /^headline_(\d+)$/.exec(k);
      if (hm) {
        const hIdx = parseInt(hm[1], 10) - 1;
        const hList = Array.isArray(gt.headlinesList) ? gt.headlinesList : [];
        if (hIdx < 0 || hIdx >= hList.length || !hList[hIdx]) v.contradictions.push('claim cites "' + k + '" but no such headline exists in the current fetch (' + hList.length + ' available)');
        continue;
      }
      if (!KEYS[k]) { v.contradictions.push('claim cites unknown factKey "' + k + '"'); continue; }
      const val = gt[k];
      if (val === undefined || val === null || val === '' || val === 'N/A') v.contradictions.push('claim cites "' + k + '" but that source is unavailable (N/A) today');
    }
    if (/\d/.test(stripStruct(c.claim))) v.contradictions.push('numeric value written in claim text (numbers must come from source injection): ' + String(c.claim).slice(0, 60));
  }
  for (const fld of ['interpretation', 'wisdom']) {
    if (/\d/.test(stripStruct(parsed[fld]))) v.contradictions.push('numeric value written in ' + fld + ' text');
  }
  const dirs = claims.map((c) => c.direction || '');
  const nBull = dirs.filter((x) => x === 'supports_bullish').length;
  const nBear = dirs.filter((x) => x === 'supports_bearish').length;
  const sent = String(parsed.sentiment || '').toLowerCase();
  if (sent.includes('bullish') && !sent.includes('bearish') && nBull === 0 && nBear > 0) v.contradictions.push('sentiment says bullish but all cited evidence supports bearish');
  if (sent.includes('bearish') && !sent.includes('bullish') && nBear === 0 && nBull > 0) v.contradictions.push('sentiment says bearish but all cited evidence supports bullish');
  v.checked = claims.length;
  if (v.contradictions.length) v.status = 'FAIL';
  v.score = Math.max(0, 100 - v.contradictions.length * 40);
  const tag3 = v.status === 'PASS' ? '✅' : '🔴';
  console.error(tag3 + ' [MarketPulse][VERIFY] ' + v.status + ' (' + edition + ', structured) claims=' + claims.length + ' violations=' + v.contradictions.length + ' score=' + v.score);
  if (v.contradictions.length) console.error('   [VERIFY] VIOLATIONS: ' + v.contradictions.join(' || '));
  if (MODE === 'enforce' && v.status === 'FAIL') {
    const n = v.contradictions.length;
    const notice = '🚫 AI analysis withheld — its reasoning failed attribution verification (' + n + ' violation' + (n === 1 ? '' : 's') + '). The verified market data above stands on its own.';
    for (const it of items) { if (!it || !it.json) continue; for (const k of ['text', 'response', 'llmAnalysis']) { if (typeof it.json[k] === 'string' && it.json[k].length > 30) it.json[k] = notice; } }
    v.action = 'withheld';
    console.error('🛡️ [MarketPulse][VERIFY] ENFORCE -> withheld (structured)');
  } else {
    let placed = false;
    for (const it of items) { if (it && it.json && it.json._health !== undefined) { it.json._structured = parsed; placed = true; } }
    if (!placed && items[0] && items[0].json) items[0].json._structured = parsed;
  }
  let att3 = false;
  for (const it of items) { if (it && it.json && it.json._health !== undefined) { it.json._verification = v; att3 = true; } }
  if (!att3 && items[0] && items[0].json) items[0].json._verification = v;
  writeLedger(parsed);
  return items;
}
// (no parseable structured output -> legacy free-text verification below)

// CHECK 1 - fabricated values for unavailable sources
for (const miss of (health && health.missing) || []) {
  const key = miss.toLowerCase().split('/')[0];
  const f = facts.find(x => x.label.toLowerCase().includes(key)) || { kw: [key] };
  for (const k of (f.kw || [])) {
    const re = new RegExp(escapeRe(k) + '[^.\\n]{0,25}?\\d', 'i');
    if (re.test(llmText)) { v.contradictions.push('Claims a value for ' + miss + ' but that source was unavailable today'); break; }
  }
}
// CHECK 2 - numeric grounding
const STOP = (n, ctx) =>
  (n === 500 && /s&p|sp500/.test(ctx)) ||
  (n === 200 && /(day|moving|ma\b|200d)/.test(ctx)) ||
  (n === 100 && /(\/100|out of 100|0-100)/.test(ctx)) ||
  (n === 300 && /csi/.test(ctx)) ||
  /\(\d|\.ss|\.sz|\.hk|hk\$/.test(ctx) ||
  ((n === 10 || n === 2) && /(year|treasury|10y|2y)/.test(ctx)) ||
  (Number.isInteger(n) && n >= 1990 && n <= 2099) ||   // a bare 4-digit year (e.g. 2024/2025), not a metric
  /v\d|version/.test(ctx);
// match whole numbers (comma-grouped OR plain runs) so years aren't split: "2024" stays "2024", not "202"+"4"
const numRe = /(\$?-?(?:\d{1,3}(?:,\d{3})+|\d+)(?:\.\d+)?)(%?)/g;
let m;
while ((m = numRe.exec(llmText)) !== null) {
  const raw = m[1] + m[2];
  const val = parseFloat(m[1].replace(/[$,]/g, ''));
  if (isNaN(val)) continue;
  const ctx = lc.slice(Math.max(0, m.index - 32), m.index + raw.length + 4);
  if (STOP(val, ctx)) continue;
  v.checked++;
  const isPct = raw.indexOf('%') !== -1;
  const cands = facts.filter(f => f.kw.some(k => ctx.includes(k)));
  if (cands.length) {
    // verified if the number matches ANY contextually-implied metric (avoids cross-metric bleed)
    if (!cands.some(f => matches(f, val))) {
      const cf = cands.find(f => isPct ? f.kind !== 'level' : f.kind === 'level') || cands[0];
      v.contradictions.push(cf.label + ': analysis says ' + raw + ', source = ' + cf.n);
    }
  } else if (!facts.some(f => matches(f, val))) {
    v.unverified.push(raw + ' (...' + ctx.trim().slice(-22) + ')');
  }
}
// CHECK 3 - directional/sentiment consistency
const fg = String(gt.fearGreedClassification || '').toLowerCase();
if (/\b(extreme greed|investors are greedy|greed dominates)\b/.test(lc) && fg.includes('fear'))
  v.contradictions.push('Says greed, but Fear & Greed = ' + gt.fearGreedClassification);
if (/\b(extreme fear|market panic|fearful sentiment)\b/.test(lc) && fg.includes('greed'))
  v.contradictions.push('Says fear, but Fear & Greed = ' + gt.fearGreedClassification);
const primaryRaw = edition === 'CN' ? gt.csi300Change : gt.sp500Change;
const primaryLabel = edition === 'CN' ? 'CSI 300' : 'S&P 500';
const pc = num(primaryRaw);
if (!isNaN(pc)) {
  if (pc < -0.1 && /\b(rally|rallied|surged|soared|broad gains|climbed higher)\b/.test(lc))
    v.contradictions.push('Says rally, but ' + primaryLabel + ' change = ' + primaryRaw);
  if (pc > 0.1 && /\b(selloff|sold off|plunged|sank|tumbled|broad declines)\b/.test(lc))
    v.contradictions.push('Says selloff, but ' + primaryLabel + ' change = ' + primaryRaw);
}
// verdict
if (v.contradictions.length) v.status = 'FAIL';
else if (v.unverified.length > 2) v.status = 'FLAG';
v.score = Math.max(0, 100 - v.contradictions.length * 40 - v.unverified.length * 8);

const tag = v.status === 'PASS' ? '✅' : (v.status === 'FAIL' ? '🔴' : '🟡');
console.error(tag + ' [MarketPulse][VERIFY] ' + v.status + ' (' + edition + ') score=' + v.score + ' | checked=' + v.checked +
  ' contradictions=' + v.contradictions.length + ' unverified=' + v.unverified.length);
if (v.contradictions.length) console.error('   [VERIFY] CONTRADICTIONS: ' + v.contradictions.join(' || '));
if (v.unverified.length) console.error('   [VERIFY] unverified: ' + v.unverified.join(' || '));

// ===== ENFORCEMENT (dormant unless MODE === 'enforce') =====
const ANALYSIS_KEYS = ['text', 'response', 'llmAnalysis'];
const rewriteAnalysis = (fn) => {
  for (const it of items) {
    if (!it || !it.json) continue;
    for (const k of ANALYSIS_KEYS) {
      if (typeof it.json[k] === 'string' && it.json[k].length > 30) it.json[k] = fn(it.json[k]);
    }
  }
};
if (MODE === 'enforce') {
  if (v.status === 'FAIL') {
    const n = v.contradictions.length;
    const notice = '🚫 AI analysis withheld — it failed automated verification against today\'s source data (' +
      n + ' contradiction' + (n === 1 ? '' : 's') + '). The verified market data above stands on its own.';
    rewriteAnalysis(() => notice);
    v.action = 'withheld';
  } else if (v.status === 'FLAG') {
    const note = '⚠️ ' + v.unverified.length + ' figure(s) below could not be verified against source data.\n\n';
    rewriteAnalysis((orig) => note + orig);
    v.action = 'flagged';
  }
  if (v.action !== 'none') console.error('🛡️ [MarketPulse][VERIFY] ENFORCE -> ' + v.action);
}

// attach verdict + pass items through (both modes return the items unchanged in structure)
let attached = false;
for (const it of items) if (it && it.json && it.json._health !== undefined) { it.json._verification = v; attached = true; }
if (!attached && items[0] && items[0].json) items[0].json._verification = v;
writeLedger(null);
return items;

} catch (e) {
  // SHADOW MODE must never break delivery: log and pass input through untouched.
  console.error('🟠 [MarketPulse][VERIFY] node error (shadow, ignored): ' + (e && e.message));
  return items;
}

// ============================================
// PREPARE DASHBOARD DATA (US) - MarketPulse
// Shapes the same verified data Compose uses into the JSON contract
// the public dashboard (docs/) reads. Code-only, no LLM involved -
// mirrors what already shipped to Telegram, doesn't reinterpret it.
// ============================================

const items = $input.all();
const d = {};
for (const item of items) {
  const j = item.json || {};
  for (const key of Object.keys(j)) {
    if (j[key] !== undefined && j[key] !== null) d[key] = j[key];
  }
}

function safe(v, fallback) {
  if (fallback === undefined) fallback = 'N/A';
  return (v === undefined || v === null || v === 'N/A' || v === '') ? fallback : v;
}

const _structured = d._structured || null;
const _health = d._health || null;

const now = new Date();
const dateLabel = now.toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });

const dashboard = {
  buffettIndicator: { title: 'Buffett Indicator', value: safe(d.buffettIndicator), status: safe(d.buffettStatus, ''), emoji: d.buffettEmoji || '' },
  shillerPE: { title: 'Shiller P/E (CAPE)', value: safe(d.shillerPE), status: safe(d.shillerStatus, ''), emoji: d.shillerEmoji || '' },
  yieldCurve: { title: 'Yield Curve (10Y-2Y)', value: safe(d.yieldCurve), status: safe(d.yieldCurveStatus, ''), emoji: d.yieldCurveEmoji || '' },
  sp500VsMa200: { title: 'S&P 500 vs 200D-MA', value: safe(d.sp500VsMa200), status: safe(d.sp500VsMa200Status, '') + (d.maSignal ? ' (' + d.maSignal + ')' : ''), emoji: d.sp500VsMa200Emoji || '' }
};

const fearGreed = (d.fearGreedValue !== undefined && d.fearGreedValue !== 'N/A')
  ? { score: d.fearGreedValue, classification: d.fearGreedClassification, change1d: d.fearGreedChange1d, change1w: d.fearGreedChange1w }
  : null;

const screener = [
  { label: 'S&P 500', factKey: 'sp500Change', value: safe(d.sp500), change: safe(d.sp500Change, '') },
  { label: 'Dow Jones', factKey: 'dowJonesChange', value: safe(d.dowJones), change: safe(d.dowJonesChange, '') },
  { label: 'VIX', factKey: 'vixChange', value: safe(d.vix), change: safe(d.vixChange, '') },
  { label: 'Gold', factKey: 'goldChange', value: safe(d.gold), change: safe(d.goldChange, '') },
  { label: 'Oil (WTI)', factKey: 'oilChange', value: safe(d.oil), change: safe(d.oilChange, '') },
  { label: 'US Dollar', factKey: 'dxyChange', value: safe(d.dxy), change: safe(d.dxyChange, '') },
  { label: 'Bitcoin', factKey: 'btcChange', value: safe(d.btc), change: safe(d.btcChange, '') }
];

const economic = [
  { label: 'GDP Growth', period: d.gdpYear || '', factKey: 'gdpValue', value: safe(d.gdpValue) },
  { label: 'Inflation/CPI', period: d.cpiYear || '', factKey: 'cpiValue', value: safe(d.cpiValue) },
  { label: 'Unemployment', period: d.unemploymentYear || '', factKey: 'unemploymentValue', value: safe(d.unemploymentValue) },
  { label: 'Fed Funds Rate', factKey: 'fedRateValue', value: safe(d.fedRateValue) },
  { label: '10Y Treasury', factKey: 'treasury10Y', value: safe(d.treasury10Y) },
  { label: '2Y Treasury', factKey: 'treasury2Y', value: safe(d.treasury2Y) }
];

const claims = (_structured && Array.isArray(_structured.claims))
  ? _structured.claims.map(function (c) { return { text: c.claim, basedOn: c.basedOn || [], direction: c.direction || 'neutral' }; })
  : [];

// ===== HISTORY (read-only): the ledger + track record already persisted by Verify AI
// Analysis and Combine All Data, read directly here (independent of $json) so the
// dashboard can show a day-by-day sentiment timeline, not just today's snapshot. =====
function buildHistory(edition) {
  try {
    const sd = $getWorkflowStaticData('global');
    const ledger = (sd.mpLedger && sd.mpLedger[edition]) || [];
    const tr = (sd.mpTrackRecord && sd.mpTrackRecord[edition]) || [];
    const scoredByPriorDate = {};
    for (const t of tr) scoredByPriorDate[t.priorDate] = t;
    return ledger.map(function (entry) {
      const scored = scoredByPriorDate[entry.date];
      return {
        date: entry.date,
        sentiment: entry.sentiment || 'n/a',
        verdict: entry.verdict || 'n/a',
        result: scored ? scored.result : null,
        actualChange: scored ? scored.actualChange : null
      };
    });
  } catch (e) { return []; }
}
const history = buildHistory('US');

const payload = {
  edition: 'US',
  generatedAt: now.toISOString(),
  dateLabel: dateLabel,
  health: _health ? { status: _health.status, missing: _health.missing || [], suspect: _health.suspect || [] } : { status: 'OK', missing: [], suspect: [] },
  dashboard: dashboard,
  fearGreed: fearGreed,
  screener: screener,
  economic: economic,
  watchlist: d.watchlistSummary || '',
  trackRecord: { accuracy: d.trackRecordAccuracy || 'Building history', last: d.trackRecordLast || '' },
  history: history,
  analysis: _structured
    ? { sentiment: _structured.sentiment || 'n/a', confidence: _structured.confidence || 'n/a', claims: claims, interpretation: _structured.interpretation || '', wisdom: _structured.wisdom || '' }
    : { sentiment: 'Unavailable', confidence: '', claims: [], interpretation: '', wisdom: '' },
  sources: ['CNN Fear & Greed', 'FRED', 'MarketWatch', 'Yahoo Finance', 'multpl.com']
};

const dashboardJson = JSON.stringify(payload, null, 2);
const commitMessage = 'Publish US dashboard data - ' + dateLabel;

return [{ json: { dashboardJson: dashboardJson, commitMessage: commitMessage } }];

